    }
};

vector<int> postorder(Node* root) {
    vector<int> result;
    if (root == nullptr) {
        return result;
    }

    // Traverse all the children
    for (Node* child : root->children) {
        vector<int> childValues = postorder(child);
        result.insert(result.end(), childValues.begin(), childValues.end());
    }

    // Append the value of the root
    result.push_back(root->val);
    return result;
}
```

Here, we're performing a recursive postorder traversal of the n-ary tree. We first recursively traverse all the children of the node, and then append the value of the current node to the postorder traversal result.

We start at the root of the tree, and keep calling the `postorder` function recursively on each child of the node. Once we have the postorder traversal of all the children, we simply append the value of the current node to the result vector and return it.

